    i = 0
    n = len(expr)
    while i < n:
        c = expr[i]
        if c.isspace():
            i += 1
            continue
        if c.isdigit():
            j = i
            while j < n and expr[j].isdigit():
                j += 1
            tokens.append(('NUM', int(expr[i:j])))
            i = j
            continue
        if c in '+-*/()':
            tokens.append((c, c))
            i += 1
            continue
        raise ValueError(f"Unexpected character: {c}")

    pos = 0

    def peek():
        if pos < len(tokens):
            return tokens[pos]
        return (None, None)

    def advance():
        nonlocal pos
        tok = tokens[pos]
        pos += 1
        return tok

    def parse_expr():
        nonlocal pos
        val = parse_term()
        while peek()[0] in ('+', '-'):
            op, _ = advance()
            rhs = parse_term()
            if op == '+':
                val = val + rhs
            else:
                val = val - rhs
        return val

    def parse_term():
        nonlocal pos
        val = parse_unary()
        while peek()[0] in ('*', '/'):
            op, _ = advance()
            rhs = parse_unary()
            if op == '*':
                val = val * rhs
            else:
                # truncate toward zero
                sign = 1
                a, b = val, rhs
                if (a < 0) ^ (b < 0):
                    sign = -1
                q = abs(a) // abs(b)
                val = sign * q
        return val

    def parse_unary():
        nonlocal pos
        if peek()[0] == '-':
            advance()
            return -parse_unary()
        return parse_primary()

    def parse_primary():
        nonlocal pos
        tok_type, tok_val = peek()
        if tok_type == 'NUM':
            advance()
            return tok_val
        if tok_type == '(':
            advance()
            val = parse_expr()
            if peek()[0] != ')':
                raise ValueError("Expected closing parenthesis")
            advance()
            return val
        raise ValueError(f"Unexpected token: {tok_type}")

    result = parse_expr()
    if pos != len(tokens):
        raise ValueError("Unexpected trailing tokens")
    return result

